    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceEvenly,
      children: digits
          .map(
            (digit) => _PinDigitButton(
              label: digit,
              onTap: () => editor._appendDigit(digit),
              enabled: !editor.widget.busy,
            ),
          )
          .toList(),
    );
  }
}

